const asyncHandler = require('../../utils/asyncHandler');
const { success } = require('../../utils/response');
const authService = require('./auth.service');
const { setAuthCookies, clearAuthCookies } = require('./cookies');
const User = require('../../models/User');
const ApiError = require('../../utils/apiError');

// POST /api/auth/google/init
// Body: { codeChallenge } - PKCE challenge generated by the frontend.
// Returns the Google consent URL. Client secret never leaves the server.
const googleInit = asyncHandler(async (req, res) => {
  const { codeChallenge } = req.body;
  const { authUrl, state } = await authService.initGoogleAuth(codeChallenge);
  return success(res, { message: 'Redirect user to authUrl', data: { authUrl, state } });
});

// POST /api/auth/google/callback
// Body: { code, state, codeVerifier }
// Exchanges the authorization code for Google tokens, verifies identity,
// finds/creates the user, and issues our own access + refresh cookies.
const googleCallback = asyncHandler(async (req, res) => {
  const { code, state, codeVerifier } = req.body;
  const ip = req.ip;
  const userAgent = req.headers['user-agent'];

  const { user, accessToken, refreshCookieToken } = await authService.completeGoogleAuth({
    code, state, codeVerifier, ip, userAgent,
  });

  setAuthCookies(res, { accessToken, refreshCookieToken });

  // For mobile (React Native) clients that can't rely on browser cookies,
  // also return the tokens in the JSON body so they can be stored in
  // secure device storage (see README "Mobile auth storage").
  return success(res, {
    status: 200,
    message: 'Authenticated successfully',
    data: {
      user: { id: user._id, name: user.name, email: user.email, profileImage: user.profileImage },
      accessToken,
      refreshToken: refreshCookieToken,
    },
  });
});

// POST /api/auth/refresh
// Reads refresh_token cookie (web) OR body.refreshToken (mobile), rotates
// the session, returns a new access token.
const refresh = asyncHandler(async (req, res) => {
  const refreshCookieToken = req.cookies.refresh_token || req.body.refreshToken;
  const ip = req.ip;
  const userAgent = req.headers['user-agent'];

  const { accessToken, refreshCookieToken: newRefreshToken } = await authService.refreshSession({
    refreshCookieToken, ip, userAgent,
  });

  setAuthCookies(res, { accessToken, refreshCookieToken: newRefreshToken });

  return success(res, {
    message: 'Session refreshed',
    data: { accessToken, refreshToken: newRefreshToken },
  });
});

// POST /api/auth/logout
const logout = asyncHandler(async (req, res) => {
  const refreshCookieToken = req.cookies.refresh_token || req.body.refreshToken;
  await authService.logout({ refreshCookieToken });
  clearAuthCookies(res);
  return success(res, { message: 'Logged out' });
});

// POST /api/auth/logout-all (requires auth) - revoke every session/device
const logoutAll = asyncHandler(async (req, res) => {
  await authService.logoutAllSessions(req.user.id);
  clearAuthCookies(res);
  return success(res, { message: 'All sessions revoked' });
});

// GET /api/auth/me (requires auth)
const me = asyncHandler(async (req, res) => {
  const user = await User.findById(req.user.id);
  if (!user) throw ApiError.notFound('User not found');
  return success(res, { data: user.toSafeJSON ? user.toSafeJSON() : user });
});

module.exports = {
  googleInit, googleCallback, refresh, logout, logoutAll, me,
};
